function BattleEndTower:InitComponent()
    if self.inited then return end
    self.inited = true
    self.items = {}
    for i = 0, 2, 1 do
        local go = KTool.Instantiate(self.RT_ItemRoot.gameObject, self.RT_Node.gameObject)
