function BattleEndTower:ShowTowerAdvance(questId)
    -- 截止到当前关卡累计的奖励
    local rewards = OverseaTowerUtils.GetQuestTotalReward(questId)
    local questVo = OverseaTowerUtils.GetTowerQuestVo(questId)

    local lastQuestId = checkNumber(questVo.unlockNum)
    local isFirstQuest = lastQuestId == 0     -- 是否是第一关
    local lastRewards = {}
    local lastQuestVo = {}
    if not isFirstQuest then
        -- 截止到上一关累计的奖励
        lastRewards = OverseaTowerUtils.GetQuestTotalReward(lastQuestId)
        lastQuestVo = OverseaTowerUtils.GetTowerQuestVo(lastQuestId)
    end

    -- 第一二个道具
    self.items[1]:ShowGood(questVo, rewards[1], 7, isFirstQuest, lastQuestVo, lastRewards[1])
    self.items[2]:ShowGood(questVo, rewards[2], 8, isFirstQuest, lastQuestVo, lastRewards[2])

    -- 第三个道具
    local isUpgrade = false
    local vo12 = QuestConfMgr:GetInstance():GetClimbTowerConfigVo(12)
    local questIds = parse_strings(vo12.num)
    for i, qId in ipairs(questIds) do
        qId = checkNumber(qId)
        if questId == qId then
            isUpgrade = true
        end
    end
    if isUpgrade then
        -- 品质提升了
        self.items[3]:ShowUpgrade(lastQuestVo, questVo, 9, self.entryDuration + 0.3)
    else
        -- 品质没有提升
        self.items[3]:ShowGood(questVo, rewards[3], 9, isFirstQuest, lastQuestVo, lastRewards[3])
    end
end

return BattleEndTower